 final LruCache<String,Bitmap> thumbs=new LruCache<String,Bitmap>(6000000){protected int sizeOf(String key,Bitmap value){return value.getRowBytes()*value.getHeight();}};ArrayList<JSONObject> mediaItems=new ArrayList<>();String mediaSignature="",mediaNotice="";long mediaLoaded=0;int browsePage=0;
