 @Override void openFrame(ArrayList<Slide> list,int index,boolean autoplay){super.openFrame(list,index,autoplay);final FramePlayer f=frame;if(f==null)return;View last=f.overlay.getChildAt(f.overlay.getChildCount()-1);if(!(last instanceof LinearLayout))return;LinearLayout row=(LinearLayout)last;row.removeAllViews();iconControl(row,"Previous",()->f.advance(-1));f.play=iconControl(row,f.playing?"Pause":"Play",()->f.toggle());iconControl(row,"Next",()->f.advance(1));f.mute=iconControl(row,f.muted?"Unmute":"Mute",()->{f.muted=!f.muted;prefs.edit().putBoolean("gallery.mute",f.muted).apply();f.volume();f.mute.setText(f.muted?"Unmute":"Mute");f.controls();});iconControl(row,"Rotate",()->screenRotation());iconControl(row,"Exit",()->home());}
 @Override void openBook(JSONObject book){super.openBook(book);if(pdf==null)return;final PdfPane pane=pdf;View a=pane.getChildAt(0),b=pane.getChildAt(pane.getChildCount()-1);if(a instanceof LinearLayout){LinearLayout row=(LinearLayout)a;row.removeAllViews();iconControl(row,"Library",()->bookshelf());iconControl(row,"Page",()->pane.jump());iconControl(row,"Bookmark",()->pane.bookmark());iconControl(row,"Saved",()->pane.saved());iconControl(row,"Rotate",()->screenRotation());}if(b instanceof LinearLayout){LinearLayout row=(LinearLayout)b;row.removeAllViews();iconControl(row,"Previous",()->pane.move(-1));iconControl(row,"Fit page",()->{pane.image.zoom=1;pane.image.panX=pane.image.panY=0;pane.image.invalidate();});iconControl(row,"Next",()->pane.move(1));}}
 String albumKey(){return "immich.albums.v2."+Base64.encodeToString(server.getBytes(),Base64.NO_WRAP|Base64.URL_SAFE);}
 LinkedHashSet<String> selection(){LinkedHashSet<String> result=new LinkedHashSet<>();if(prefs.contains(albumKey()))result.addAll(prefs.getStringSet(albumKey(),new HashSet<>()));else if(!get("gallery.album").isEmpty())result.add(get("gallery.album"));return result;}
 void choose(Set<String> ids){prefs.edit().putStringSet(albumKey(),new HashSet<>(ids)).apply();albumFilter="";save("gallery.album","");mediaItems.clear();mediaSignature="";browsePage=0;prefs.edit().putBoolean("gallery.local",false).apply();}
 String selectionLabel(){int n=selection().size();return n==0?"Whole Immich library":n+" selected album"+(n==1?"":"s");}
 @Override void forget(){prefs.edit().remove(albumKey()).apply();mediaItems.clear();mediaSignature="";thumbs.evictAll();super.forget();}
 void thumb(ImageView view,String s,String t,String id){if(id==null||!id.matches("[A-Za-z0-9-]+"))return;String key=s+"|"+t+"|"+id;Bitmap cached=thumbs.get(key);if(cached!=null){view.setImageBitmap(cached);return;}int stamp=revision;work(()->{byte[] bytes=request(s+"/assets/"+id+"/thumbnail?size=thumbnail","GET",null,t,5000000);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>480||options.outHeight/options.inSampleSize>360)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(image==null)return;thumbs.put(key,image);ui.post(()->{if(stamp==revision)view.setImageBitmap(image);});});}
 @Override void albums(){if(token.isEmpty()){immich();return;}page("Choose your albums");text("Tap album covers to select one or more. Apply for browsing or play them together. Nothing changes on your Immich server.");LinkedHashSet<String> selected=selection();TextView summary=new TextView(this);summary.setTextColor(accent);summary.setTextSize(18);summary.setText(selected.size()+" selected");body.addView(summary);button("Apply selected albums / browse",()->{if(selected.isEmpty()){toast("Choose an album or use Whole library");return;}choose(selected);library();});button("Play selected albums fullscreen",()->{if(selected.isEmpty()){toast("Choose an album or use Whole library");return;}choose(selected);startGallery(false);});button("Use whole library",()->{choose(new HashSet<>());library();});EditText search=input("Search album names","");LinearLayout covers=new LinearLayout(this);covers.setOrientation(1);body.addView(covers);final int[] page={0};final Runnable[] render={()->{}};button("Previous album page",()->{page[0]=Math.max(0,page[0]-1);render[0].run();});button("Next album page",()->{page[0]++;render[0].run();});final String s=server,t=token;int stamp=revision;work(()->{JSONArray response=new JSONArray(new String(request(s+"/albums","GET",null,t,6000000),"UTF-8"));ArrayList<JSONObject> all=new ArrayList<>();for(int i=0;i<response.length();i++)all.add(response.getJSONObject(i));Collections.sort(all,(a,b)->a.optString("albumName").compareToIgnoreCase(b.optString("albumName")));ui.post(()->{if(stamp!=revision)return;render[0]=()->{covers.removeAllViews();ArrayList<JSONObject> found=new ArrayList<>();String query=search.getText().toString().toLowerCase(Locale.getDefault());for(JSONObject album:all)if(album.optString("albumName").toLowerCase(Locale.getDefault()).contains(query))found.add(album);int first=Math.min(page[0]*24,Math.max(0,(found.size()-1)/24*24));int cols=getResources().getConfiguration().screenWidthDp>=950?3:2;LinearLayout row=null;int count=0;for(int i=first;i<Math.min(first+24,found.size());i++){JSONObject album=found.get(i);String id=album.optString("id");if(count%cols==0){row=new LinearLayout(this);covers.addView(row);}LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(shape(selected.contains(id)?0xff223b4b:surface,selected.contains(id)?accent:edge,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(235),1);cp.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(card,cp);ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackground(shape(0xff26334d,0,12));card.addView(cover,new LinearLayout.LayoutParams(-1,dp(135)));thumb(cover,s,t,album.optString("albumThumbnailAssetId"));TextView name=new TextView(this);name.setText(album.optString("albumName","Album"));name.setTextColor(fg);name.setTextSize(18);name.setMaxLines(2);card.addView(name);TextView details=new TextView(this);details.setText(album.optInt("assetCount")+" items / "+(selected.contains(id)?"Selected":"Tap to select"));details.setTextColor(accent);details.setTextSize(12);card.addView(details);card.setContentDescription(name.getText()+". "+details.getText());card.setOnClickListener(v->{if(selected.contains(id))selected.remove(id);else{if(selected.size()>=12){toast("Choose up to 12 albums per gallery");return;}selected.add(id);}summary.setText(selected.size()+" selected");card.setBackground(shape(selected.contains(id)?0xff223b4b:surface,selected.contains(id)?accent:edge,18));details.setText(album.optInt("assetCount")+" items / "+(selected.contains(id)?"Selected":"Tap to select"));});count++;}if(row!=null&&count%cols!=0)for(int i=count%cols;i<cols;i++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));if(found.isEmpty()){TextView empty=new TextView(this);empty.setText("No matching albums. Shared albums appear only if your account can access them.");empty.setTextColor(muted);covers.addView(empty);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence value,int a,int c,int f){}public void onTextChanged(CharSequence value,int start,int before,int count){page[0]=0;render[0].run();}public void afterTextChanged(Editable e){}});render[0].run();});});}
 void saveSessionIfNeeded(){if(Build.VERSION.SDK_INT>=18){remember("");return;}if(!get("immich.vault").isEmpty()||rememberAsked)return;rememberAsked=true;EditText secret=new EditText(this);secret.setInputType(129);secret.setHint("Separate unlock passphrase / 10+ characters");new android.app.AlertDialog.Builder(this).setTitle("Remember sign-in").setMessage("Android 4.2 needs a separate unlock passphrase to encrypt the saved session.").setView(secret).setPositiveButton("Save",(d,w)->remember(secret.getText().toString())).setNegativeButton("Not now",null).show();}
 String signature(String s,String t,Set<String> ids){return s+"|"+t+"|"+new TreeSet<>(ids).toString();}
 interface Loaded {void accept(ArrayList<JSONObject> items);}
 void loadSelection(Loaded callback){final String s=server,t=token;final LinkedHashSet<String> ids=selection();final String sig=signature(s,t,ids);if(sig.equals(mediaSignature)&&System.currentTimeMillis()-mediaLoaded<300000L){callback.accept(new ArrayList<>(mediaItems));return;}final int stamp=revision;work(()->{ArrayList<String> sources=new ArrayList<>(ids);if(sources.isEmpty())sources.add("");int n=sources.size();int[] pages=new int[n];Arrays.fill(pages,1);String[] cursors=new String[n];Arrays.fill(cursors,"");boolean[] active=new boolean[n];Arrays.fill(active,true);HashSet<String> seen=new HashSet<>();ArrayList<JSONObject> result=new ArrayList<>();int requests=0;boolean again=true;while(again&&requests<100&&result.size()<5000){again=false;for(int i=0;i<n;i++){if(!active[i])continue;again=true;if(stamp!=revision||!server.equals(s)||!token.equals(t))return;if(requests>=100||result.size()>=5000)break;JSONObject query=new JSONObject().put("size",100);if(cursors[i].isEmpty())query.put("page",pages[i]);else query.put("cursor",cursors[i]);if(!sources.get(i).isEmpty())query.put("albumIds",new JSONArray().put(sources.get(i)));requests++;JSONObject group=new JSONObject(new String(request(s+"/search/metadata","POST",query.toString(),t,6000000),"UTF-8")).getJSONObject("assets");JSONArray items=group.getJSONArray("items");for(int j=0;j<items.length()&&result.size()<5000;j++){JSONObject item=items.getJSONObject(j);String type=item.optString("type");if((type.equals("IMAGE")||type.equals("VIDEO"))&&seen.add(item.optString("id")))result.add(item);}String cursor=group.isNull("nextCursor")?"":group.optString("nextCursor","");String page=group.isNull("nextPage")?"":group.optString("nextPage","");if(items.length()==0)active[i]=false;else if(!cursor.isEmpty()&&!cursor.equals(cursors[i]))cursors[i]=cursor;else if(!page.isEmpty()){int next=Integer.parseInt(page);if(next<=pages[i])active[i]=false;else{pages[i]=next;cursors[i]="";}}else active[i]=false;}}boolean partial=false;for(boolean a:active)if(a)partial=true;final String notice=partial?"Showing a bounded selection (5,000 items / 100 metadata requests maximum).":"";ui.post(()->{if(stamp!=revision||!server.equals(s)||!token.equals(t))return;mediaItems=new ArrayList<>(result);mediaSignature=sig;mediaLoaded=System.currentTimeMillis();mediaNotice=notice;callback.accept(result);});});}
 @Override void library(){if(token.isEmpty()){immich();return;}saveSessionIfNeeded();page("Your photo library");text(selectionLabel());button("Choose albums",()->albums());button("Play selected gallery fullscreen",()->startGallery(false));button("Whole library / clear album filter",()->{choose(new HashSet<>());library();});button("Refresh media",()->{mediaSignature="";library();});button("Forget saved login / sign out",()->forget());text("Loading thumbnails...");loadSelection(items->browse(items));}
 void browse(ArrayList<JSONObject> items){page("Your photo library");text(selectionLabel()+" / "+items.size()+" photos and videos");button("Choose albums",()->albums());button("Play fullscreen",()->startGallery(false));button("Refresh media",()->{mediaSignature="";library();});button("Whole library / clear filter",()->{choose(new HashSet<>());library();});button("Sign out / forget saved login",()->forget());if(!mediaNotice.isEmpty())text(mediaNotice);assets=new JSONArray();for(JSONObject item:items)assets.put(item);if(items.isEmpty())text("No media found in this selection. Choose different albums or Whole library.");int first=Math.min(browsePage*24,Math.max(0,(items.size()-1)/24*24));int cols=getResources().getConfiguration().screenWidthDp>=950?3:2;LinearLayout row=null;int count=0;for(int i=first;i<Math.min(first+24,items.size());i++){JSONObject item=items.get(i);final int index=i;if(count%cols==0){row=new LinearLayout(this);body.addView(row);}LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(10),dp(10),dp(10),dp(10));card.setBackground(press(surface));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(215),1);cp.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(card,cp);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(-1,dp(150)));thumb(image,server,token,item.optString("id"));TextView caption=new TextView(this);caption.setText(item.optString("originalFileName","Memory"));caption.setTextColor(fg);caption.setTextSize(14);caption.setMaxLines(1);card.addView(caption);TextView kind=new TextView(this);kind.setText(item.optString("type").equals("VIDEO")?"Video / tap to play":"Photo / tap to open");kind.setTextColor(accent);kind.setTextSize(12);card.addView(kind);card.setOnClickListener(v->{position=index;showAsset(false);});count++;}if(row!=null&&count%cols!=0)for(int i=count%cols;i<cols;i++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));button("Previous media page",()->{browsePage=Math.max(0,browsePage-1);browse(items);});button("Next media page",()->{browsePage++;browse(items);});}
 @Override void startGallery(boolean local){if(local){super.startGallery(true);return;}prefs.edit().putBoolean("gallery.local",false).apply();if(token.isEmpty()){immich();return;}page("Preparing your gallery");text(selectionLabel());text("Collecting photos and videos from the chosen albums...");final String s=server,t=token;loadSelection(items->{ArrayList<Slide> slides=new ArrayList<>();JSONArray values=new JSONArray();for(JSONObject item:items)values.put(item);slides.addAll(remoteSlides(values,s,t));if(slides.isEmpty()){text("No playable media found. Choose albums from the library.");button("Choose albums",()->albums());return;}if(prefs.getBoolean("gallery.shuffle",false))Collections.shuffle(slides);openFrame(slides,0,true);});}
